mapper.select:
del_flag = '0'
and ( name_cn ILIKE CONCAT('%', #{searchQuery}, '%') or name_vn ILIKE CONCAT('%', #{searchQuery}, '%') or name_en ILIKE CONCAT('%', #{searchQuery}, '%') or aka::text ILIKE CONCAT('%', #{searchQuery}, '%') or tax_code ILIKE CONCAT('%', #{searchQuery}, '%') or risk_reason ILIKE CONCAT('%', #{searchQuery}, '%') or issuing_agency ILIKE CONCAT('%', #{searchQuery}, '%') or matched_enterprise_code ILIKE CONCAT('%', #{searchQuery}, '%') )
and risk_category = #{riskCategory}
and risk_level = #{riskLevel}
and entity_type = #{entityType}
order by update_time desc nulls last, name_cn asc
